panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:56px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:30px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:62px;font-weight:900;line-height:1.24;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.note{position:absolute;left:60px;right:60px;bottom:40px;font-size:22px}
.tbl{margin-top:36px;background:#fff;border-radius:26px;padding:14px 26px;box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.h,.r{display:grid;grid-template-columns:70px 1fr 220px 230px;align-items:center;gap:12px}
.h{font-size:22px;color:var(--ink-2);font-weight:700;padding:8px 0;border-bottom:2px solid #eadde3}.h span:nth-child(n+3){text-align:right}
.r{padding:18px 0;border-bottom:2px dashed #eadde3}.r:last-child{border-bottom:0}
.no{width:56px;height:56px;border-radius:50%;background:#46293A;color:#fff;font-size:30px;font-weight:900;display:flex;align-items:center;justify-content:center}
.r.top .no{background:#D63E76}.r.low .no{background:#9a8a92}
.nm img{height:54px;max-width:300px;object-fit:contain}.nm.tx{font-size:34px;font-weight:900}
.cb{text-align:right;font-size:28px;font-weight:700;color:var(--ink-2)}
.r.top .cb{color:#D63E76;font-weight:900}
.yen{text-align:right;font-size:38px;font-weight:900}
.r.top .yen{color:#D63E76;font-size:44px}
.one{margin-top:28px;text-align:center;font-size:32px;font-weight:700;background:#46293A;color:#fff;border-radius:18px;padding:18px 16px}.one b{color:#F5C518;font-weight:900}
